// Logos de bancos y servicios, fuera del index.html a propósito.
//
// Eran ~361kb de base64 embebidos en el HTML: un tercio del archivo, que se
// volvía a bajar entero en cada actualización de la app aunque ningún logo
// hubiera cambiado. Acá se bajan una vez y el service worker los deja en su
// propia caché (ASSETS_CACHE), que sobrevive a los cambios de versión.
//
// Recomprimidos a WebP de 128px: el mayor tamaño en pantalla es 38px, así
// que cubre 3x de densidad. Los originales eran JPEG de hasta 1200px
// declarados como image/png (funcionaba porque el navegador lo detecta solo).
//
// Si cambia alguno, subir el ?v= del <script> en index.html — es la clave de
// caché, si no el service worker sigue sirviendo el viejo.
//
// Se exponen en window.LOGOS y no como const sueltas: si este archivo no
// carga, index.html cae al ícono genérico en vez de romper toda la app con
// un ReferenceError.
window.LOGOS={
MP:'data:image/webp;base64,',
SANT:'data:image/webp;base64,',
MACRO:'data:image/webp;base64,',
NX:'data:image/webp;base64,',
NETFLIX:'data:image/webp;base64,',
HBO:'data:image/webp;base64,',
SPOTIFY:'data:image/webp;base64,',
AGUA:'data:image/webp;base64,',
LUZ:'data:image/webp;base64,',
GAS:'data:image/webp;base64,',
CLAUDE:'data:image/webp;base64,',
UBER:'data:image/webp;base64,',
RAPPI:'data:image/webp;base64,',
ARCA:'data:image/webp;base64,',
CLARO:'data:image/webp;base64,',
TUENTI:'data:image/webp;base64,',
EDESUR:'data:image/webp;base64,',
SPORTCLUB:'data:image/webp;base64,',
};
